import { Buffer } from "node:buffer";

const document = "";

export function GET() {
  return new Response(new Uint8Array(Buffer.from(document, "base64")), {
    headers: {
      "Content-Type": "application/pdf",
      "Content-Disposition": "attachment; filename=RBA_Shooting_Practice_Observation.pdf",
      "Cache-Control": "public, max-age=3600",
      "X-Content-Type-Options": "nosniff",
    },
  });
}
